/* ═══════════════════════════════════════════════════════════
   LOADING SCREEN (Step 0)
   ═══════════════════════════════════════════════════════════ */
function LoadingScreen({ onComplete }: { onComplete: () => void }) {
  const [progress, setProgress] = useState(0);
  const [messageIndex, setMessageIndex] = useState(0);

  const messages = [
    "Securing your discount...",
    "Checking stock availability...",
    "Applying your savings...",
    "Preparing your order...",
  ];

  useEffect(() => {
    const duration = 2500;
    const interval = 30;
    let elapsed = 0;

    const timer = setInterval(() => {
      elapsed += interval;
      const t = elapsed / duration;
      const eased = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
      setProgress(Math.min(eased * 100, 100));

      if (t > 0.25 && messageIndex < 1) setMessageIndex(1);
      if (t > 0.5 && messageIndex < 2) setMessageIndex(2);
      if (t > 0.75 && messageIndex < 3) setMessageIndex(3);

      if (elapsed >= duration) {
        clearInterval(timer);
        setTimeout(onComplete, 300);
      }
    }, interval);

    return () => clearInterval(timer);
  }, [onComplete]);

  return (
    <div className="min-h-screen bg-[#FAF3EF] flex items-center justify-center p-4">
      <div className="w-full max-w-sm text-center">
        <div className="mb-8 flex justify-center">
          <div className="w-16 h-16 rounded-2xl bg-white shadow-lg flex items-center justify-center animate-pulse">
            <FluffLogo className="h-7 w-auto" color="#2d3a5c" />
          </div>
        </div>
        <p className="text-sm font-medium text-[#2d3a5c] mb-6 h-5 transition-all duration-300">
          {messages[messageIndex]}
        </p>
        <div className="w-full h-2 bg-gray-200 rounded-full overflow-hidden mb-3">
          <div
            className="h-full bg-gradient-to-r from-[#2d3a5c] to-[#424680] rounded-full transition-all duration-75 ease-linear"
            style={{ width: `${progress}%` }}
          />
        </div>
        <p className="text-xs text-muted-foreground">{Math.round(progress)}%</p>
        <div className="mt-8 flex items-center justify-center gap-4 text-[10px] text-muted-foreground">
          <span className="flex items-center gap-1"><Lock className="w-3 h-3" /> 256-bit SSL</span>
          <span className="flex items-center gap-1"><Shield className="w-3 h-3" /> Secure Checkout</span>
        </div>
      </div>
    </div>
  );
}

