/* ═══════════════════════════════════════════════════════════
   PROGRESS BAR (minimal, vague labels)
   ═══════════════════════════════════════════════════════════ */
function ProgressBar({ currentStep }: { currentStep: number }) {
  return (
    <div className="flex items-center justify-center gap-1 py-3 px-4">
      {STEP_LABELS.map((label, idx) => {
        const isActive = idx + 1 === currentStep;
        const isCompleted = idx + 1 < currentStep;
        return (
          <div key={idx} className="flex items-center">
            {idx > 0 && <ChevronRight className="w-3 h-3 text-gray-300 mx-0.5 flex-shrink-0" />}
            <span
              className={`text-[11px] font-medium px-2 py-1 rounded-full whitespace-nowrap transition-all ${
                isActive
                  ? "bg-[#2d3a5c] text-white"
                  : isCompleted
                  ? "text-[#2d3a5c]"
                  : "text-gray-400"
              }`}
            >
              {isCompleted && <Check className="w-3 h-3 inline mr-0.5" />}
              {label}
            </span>
          </div>
        );
      })}
    </div>
  );
}

